def page(title,body): return HEAD.format(title=title)+body+FOOT
def frame(inner,extra=''): return f'<div style="width: 1440px; height: 900px; position: relative; overflow: hidden; {WALL}; color: #ECEEF3; font-family: Geist, system-ui, sans-serif; font-size: 14px">{inner}</div>\n'
def win(x,y,w,h,title,body,z=2,right_ctrl=False,pill=False):
    ctr=lights()
    head=(f'<div style="height: 40px; display: flex; align-items: center; gap: 12px; padding: 0 12px; border-bottom: 1px solid rgba(255,255,255,.07)">'
          +('' if right_ctrl else ctr)+f'<span style="flex: 1; text-align: center; font-weight: 600">{title}</span>'+(PILL if pill else '')+(ctr if right_ctrl else '')+'</div>')
    return f'<section aria-label="{title}" style="position: absolute; left: {x}px; top: {y}px; width: {w}px; height: {h}px; border-radius: 14px; background: rgba(18,20,28,.95); border: 1px solid rgba(255,255,255,.1); box-shadow: 0 40px 90px rgba(0,0,0,.6); overflow: hidden; display: flex; flex-direction: column; z-index: {z}">{head}<div style="flex: 1; min-height: 0; display: flex; flex-direction: column">{body}</div></section>'
