c['notes']['osLook']['text']=("Ortus OS UI rules\n• No global app menus (COSMIC has none; Wayland protocol not standard yet) — menus stay in windows; top bar = app name + status\n"
 "• Two layouts set by IT: Modern (top bar + dock) and Classic (bottom taskbar) for Windows users\n• Shortcuts shown as Ctrl / Super, never ⌘; keyboard layout always visible\n"
 "• Own window controls (glyphs, Ortus colours); GTK/Qt themes so Firefox, LibreOffice match\n• Classification label per window, not per desktop\n• Mic/camera/screen-share indicator in top bar; system prompts striped + mirrored on phone\n"
 "• Glass falls back to solid on weak GPUs, VMs, remote desktop; always a scrim under text\n• Dock magnification optional\n• Ortus apps = same web UI in a native Rust shell; one token set for web + OS\n"
 "• Screen reader: fix AccessKit gaps in libcosmic (text fields) and contribute upstream")
c['notes']['osLook']['h']=None; c['notes']['osLook'].pop('h')
json.dump(c,open(D+'canvas.json','w'),ensure_ascii=False)
